%[text] # Visualize data - vehicle speed reference
speed_unit = "km/hr";
% speed_unit = "mph";
% speed_unit = "m/s";
%[text] ## Simple
% This script populates the `VehicleSpeedRef` table data in the base workspace.
loadLUTData_VehSpdRef_Simple
createPlot_VehSpdRef(VehicleSpeedRef, SpeedUnit=speed_unit) %[output:83657a9f]
%[text] ## High speed
data_table = BuildData_VehSpdRef_HighSpeed();
createPlot_VehSpdRef(data_table, SpeedUnit=speed_unit) %[output:06d76b96]
